import type { Project, ActionKind, ContinueConfirmation, VerificationResult } from '../types'
import type { State } from './logic'
import { hasAsk, parseGate } from './logic'

export const ACTION_LABEL: Record<ActionKind, string> = {
  verify: '▶ 執行驗證', sync: '⇢ 同步 STATUS', continue: '⇢ 繼續下一步',
  decide: '✎ 做決定', gate: '⚑ 審核關卡', open: '↗ 開啟 STATUS.md',
}

export function actionLabel(kind: ActionKind, project: Project): string {
  return kind === 'gate' && parseGate(project.gate)?.kind === 'release' ? '⚑ 最終審核' : ACTION_LABEL[kind]
}

export function dispatchBlockReason(project: Project): string {
  const active = project.jobs.filter(job => job.kind === 'running')
  return active.length ? `${[...new Set(active.map(job => job.executor ?? '執行者'))].join(' / ')} 工作尚未結束` : ''
}

/** A `manual` project is handoff-only: the panel never dispatches it, CARD/verify/gates still work. */
export const isManual = (project: Project) => project.executor === 'manual'

export function actionKinds(project: Project, state: State): ActionKind[] {
  const kinds: ActionKind[] = []
  const dispatchable = !isManual(project)
  if (project.verify.trim()) kinds.push('verify')
  if (dispatchable && state === 'SYNC' && !dispatchBlockReason(project)) kinds.push('sync')
  const gate = parseGate(project.gate)
  const next = project.next.trim()
  if (dispatchable && state === 'IDLE' && !dispatchBlockReason(project) && next && !/^(?:無|沒有|none|n\/a|-)(?:$|[；;，,。\s])/i.test(next) && !hasAsk(project) && !gate) kinds.push('continue')
  if (hasAsk(project)) kinds.push('decide')
  if (gate && gate.kind !== 'unknown') kinds.push('gate')
  return [...kinds, 'open']
}

export function dispatchPrompt(project: Project, kind: 'sync' | 'continue'): string {
  const instruction = kind === 'sync'
    ? '把最近完成的工作結果寫回 STATUS CARD，只改 CARD 與歷程，不做其他變更'
    : '依 STATUS CARD 的下一步繼續；遵守任務骨架；結束時更新 CARD（含關卡欄）'
  return `${instruction}\nSTATUS：${project.statusPath}\n只在此專案授權的本機範圍作業。不得執行正式環境變更或 release；需要上線時填入 release 關卡，交主控台整理後由使用者決定。`
}

export function gatePrompt(project: Project): string {
  const gate = parseGate(project.gate)
  if (!gate || gate.kind === 'unknown') throw new Error('關卡種類無法辨識；請先檢查 STATUS。')
  const base = `依 claude-console skill 審核「${project.name}」的 ${gate.kind} 關卡。`
  return gate.kind === 'release'
    ? `${base}整理成「可上線／不可上線＋理由＋要使用者確認的一句」；不得自行執行 release 或任何正式環境變更。`
    : `${base}依證據判斷，指出結果與理由，更新關卡結論；不得執行 release 或正式環境變更。`
}

export function workSignature(project: Project): string {
  return JSON.stringify([project.statusPath, project.updated, project.next, project.ask, project.gate ?? ''])
}

export function confirmationMatches(value: ContinueConfirmation | undefined, signature: string, now: number): boolean {
  return !!value && value.signature === signature && now >= value.at && now - value.at < 3000
}

/** CARD verification is a shell command, run in the project's directory, not the console's. */
export function verificationArgs(command: string, windows: boolean): string[] {
  if (!windows) return ['sh', '-lc', command]
  return ['powershell', '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-Command',
    `$ErrorActionPreference = 'Stop'; & { ${command}\n}; $consoleVerifyOK = $?; if ($null -ne $LASTEXITCODE -and $LASTEXITCODE -ne 0) { exit $LASTEXITCODE }; if (-not $consoleVerifyOK) { exit 1 }`]
}

/** The API returns separate streams; append stderr, then keep only the final three nonblank lines. */
export function outputTail(stdout: string, stderr = ''): string[] {
  return `${stdout}\n${stderr}`.replace(/\x1b\[[0-?]*[ -/]*[@-~]/g, '').split(/\r?\n/).map(s => s.trimEnd()).filter(s => s.trim()).slice(-3).map(s => s.slice(0, 500))
}

export function verificationResult(command: string, at: number, result: { exitCode: number; stdout: string; stderr: string; isStdoutTruncated?: boolean; isStderrTruncated?: boolean }): VerificationResult {
  return { command, at, ok: result.exitCode === 0, exitCode: result.exitCode, lines: outputTail(result.stdout, result.stderr), truncated: !!(result.isStdoutTruncated || result.isStderrTruncated) }
}

export function launchId(stdout: string): string | null {
  try {
    const data = JSON.parse(stdout.trim())
    return typeof data?.jobId === 'string' && data.jobId.trim() ? data.jobId : null
  } catch { return null }
}

files.hooks/companion.ts:
// Locate codex-companion.mjs when the configured path is empty or stale (the Codex plugin
// installs each version into its own cache folder, so a pinned path goes stale on update).

export type CompanionFiles = {
  read(path: string): Promise<string>
  list(path: string): Promise<{ name: string; kind: string }[]>
}
export type CompanionSource = 'configured' | 'installed' | 'cache' | 'none'
export type CompanionResolution = { path: string; source: CompanionSource; version?: string; warning?: string }

const PLUGIN_ID = 'codex@openai-codex'
const SCRIPT = 'scripts/codex-companion.mjs'
const SEMVER = /^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?$/
const slash = (value: string) => value.replace(/\\/g, '/').replace(/\/+$/, '')

/** Semantic-version order (1.0.10 > 1.0.9; a pre-release sorts before its release); null if not semver. */
export function compareSemver(a: string, b: string): number | null {
  const x = a.trim().match(SEMVER)
  const y = b.trim().match(SEMVER)
  if (!x || !y) return null
  for (let i = 1; i <= 3; i++) {
    const d = Number(x[i]) - Number(y[i])
    if (d) return Math.sign(d)
  }
  const pa = x[4], pb = y[4]
  if (!pa || !pb) return pa === pb ? 0 : pa ? -1 : 1
  const left = pa.split('.'), right = pb.split('.')
  for (let i = 0; i < Math.max(left.length, right.length); i++) {
    const l = left[i], r = right[i]
    if (l === undefined) return -1
    if (r === undefined) return 1
    const ln = /^\d+$/.test(l), rn = /^\d+$/.test(r)
    if (ln && rn && Number(l) !== Number(r)) return Math.sign(Number(l) - Number(r))
    if (ln !== rn) return ln ? -1 : 1
    if (l !== r) return l < r ? -1 : 1
  }
  return 0
}

/** The highest semantic version among names; non-semver names are ignored. */
export function newestVersion(names: string[]): string | null {
  let best: string | null = null
  for (const name of names) {
    if (compareSemver(name, name) === null) continue
    if (best === null || (compareSemver(name, best) ?? 0) > 0) best = name
  }
  return best
}

/** Install paths recorded for the Codex plugin, newest version first. */
export function installedPaths(text: string | null): { path: string; version?: string }[] {
  try {
    const data = JSON.parse((text ?? '').replace(/^﻿/, ''))
    const entries = data?.plugins?.[PLUGIN_ID]
    const list = Array.isArray(entries) ? entries : entries && typeof entries === 'object' ? [entries] : []
    const out: { path: string; version?: string }[] = []
    for (const entry of list) {
      if (!entry || typeof entry !== 'object' || typeof entry.installPath !== 'string' || !entry.installPath.trim()) continue
      const version = typeof entry.version === 'string' && compareSemver(entry.version, entry.version) !== null ? entry.version
        : slash(entry.installPath).split('/').pop()
      out.push({ path: slash(entry.installPath), ...(version && compareSemver(version, version) !== null ? { version } : {}) })
    }
    return out.sort((a, b) => (b.version && a.version ? compareSemver(b.version, a.version) ?? 0 : a.version ? -1 : b.version ? 1 : 0))
  } catch { return [] }
}

async function fileExists(files: CompanionFiles, path: string): Promise<boolean> {
  const normalized = slash(path)
  const cut = normalized.lastIndexOf('/')
  if (cut <= 0) return false
  const entries = await files.list(normalized.slice(0, cut)).catch(() => [])
  const name = normalized.slice(cut + 1).toLowerCase()
  return entries.some(entry => entry?.kind !== 'dir' && typeof entry?.name === 'string' && entry.name.toLowerCase() === name)
}

/**
 * Pick the companion script. `configuredMissing` comes from a caller that already knows the
 * configured file is absent (the preflight's `companion=MISSING`). An existing configured path wins;
 * otherwise the newest semver among installed_plugins.json install paths and
 * `~/.claude/plugins/cache/openai-codex/codex/<version>/` that actually contains the script.
 */
export async function resolveCompanion(files: CompanionFiles, home: string, configured: string, configuredMissing = false): Promise<CompanionResolution> {
  const wanted = slash(configured.trim())
  if (wanted && !configuredMissing) return { path: wanted, source: 'configured' }
  const base = slash(home)
  const candidates: { path: string; version: string; source: CompanionSource }[] = []
  const installed = installedPaths(await files.read(`${base}/.claude/plugins/installed_plugins.json`).catch(() => null))
  for (const entry of installed) {
    if (entry.version) candidates.push({ path: `${entry.path}/${SCRIPT}`, version: entry.version, source: 'installed' })
  }
  const cacheRoot = `${base}/.claude/plugins/cache/openai-codex/codex`
  const versions = (await files.list(cacheRoot).catch(() => []))
    .filter(entry => entry?.kind === 'dir' && typeof entry.name === 'string' && compareSemver(entry.name, entry.name) !== null)
    .map(entry => entry.name)
  for (const version of versions) candidates.push({ path: `${cacheRoot}/${version}/${SCRIPT}`, version, source: 'cache' })
  // Newest first; on a tie the installed record wins because it was pushed first and sort is stable.
  candidates.sort((a, b) => compareSemver(b.version, a.version) ?? 0)
  for (const candidate of candidates) {
    if (wanted && candidate.path.toLowerCase() === wanted.toLowerCase()) continue
    if (!await fileExists(files, candidate.path)) continue
    return {
      path: candidate.path, source: candidate.source, version: candidate.version,
      ...(wanted ? { warning: `configured companionScript not found (${wanted}); using ${candidate.version}` } : {}),
    }
  }
  return wanted
    ? { path: wanted, source: 'configured', warning: `configured companionScript not found (${wanted}) and no installed Codex plugin was found` }
    : { path: '', source: 'none', warning: 'companionScript is empty and no installed Codex plugin was found' }
}

files.hooks/fallback.ts:
// Decide whether a Codex dispatch should go ahead, fall back to Claude, or ask the operator.
import type { FallbackMode } from './config'

export const QUOTA_STALE_MS = 6 * 3_600_000

export type CodexQuota = { at: string; limits: { label: string; percent: number; resetsAt?: string }[] } | null | undefined
export type QuotaReading = { state: 'ok' | 'low' | 'unknown'; remaining: number | null; ageMs: number | null }
export type FallbackDecision =
  | { action: 'codex' }
  | { action: 'claude'; reason: string }
  | { action: 'ask'; reason: string }

/**
 * Lowest remaining percentage across the quota windows. A reading older than six hours,
 * without a timestamp, or without windows is `unknown` and never triggers a fallback by itself.
 */
export function quotaReading(quota: CodexQuota, minPercent: number, now: number): QuotaReading {
  if (!quota || !quota.limits.length) return { state: 'unknown', remaining: null, ageMs: null }
  const at = Date.parse(quota.at)
  if (!Number.isFinite(at)) return { state: 'unknown', remaining: null, ageMs: null }
  const ageMs = Math.max(0, now - at)
  const remaining = Math.min(...quota.limits.map(limit => Math.max(0, Math.min(100, Math.round(100 - limit.percent)))))
  if (ageMs > QUOTA_STALE_MS) return { state: 'unknown', remaining, ageMs }
  return { state: remaining < minPercent ? 'low' : 'ok', remaining, ageMs }
}

/** Why the preflight line (already filtered to this project's workspace) blocks Codex, or ''. */
export function preflightProblem(line: string, companionPath: string): string {
  const text = line.trim()
  if (text.startsWith('STALE')) return 'Codex broker 過期（Codex app 已更新）'
  if (/\bcodex=unavailable\b/.test(text)) return '找不到 Codex app／broker'
  if (/\bcompanion=MISSING\b/.test(text)) return '找不到 codex-companion.mjs'
  if (!companionPath.trim()) return '未設定且找不到 codex-companion.mjs'
  return ''
}

export type FallbackInput = {
  mode: FallbackMode
  minPercent: number
  quota: CodexQuota
  preflight: string
  companionPath: string
  now: number
}

/** `off` keeps the 0.1 behavior: always try Codex. */
export function decideCodexDispatch(input: FallbackInput): FallbackDecision {
  if (input.mode === 'off') return { action: 'codex' }
  const reasons: string[] = []
  const problem = preflightProblem(input.preflight, input.companionPath)
  if (problem) reasons.push(problem)
  const quota = quotaReading(input.quota, input.minPercent, input.now)
  if (quota.state === 'low') reasons.push(`Codex 額度剩 ${quota.remaining}%（低於 ${input.minPercent}%）`)
  if (!reasons.length) return { action: 'codex' }
  return { action: input.mode === 'claude' ? 'claude' : 'ask', reason: reasons.join('；') }
}

